draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // stick figure
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // chain
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2, H);
  ctx.stroke();

  // breaking chain
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70 + 20*Math.sin(t));
  ctx.lineTo(W/2, H);
  ctx.stroke();

  // balloon
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 70 + 20*Math.sin(t) - 20, 10, 0, 2*Math.PI);
  ctx.stroke();

  // memory bubble
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Memory', W/2, H/2 - 50);

  ctx.restore();
}
